et:2px}.checkbox{display:flex;align-items:center;gap:8px;margin:4px 0 20px;color:#586173;font-size:13px}.checkbox input{accent-color:var(--primary)}.auth-button,.btn{width:100%;min-height:50px;border:0;border-radius:12px;background:var(--primary);color:#fff;font:700 15px inherit;cursor:pointer;transition:background .18s,transform .18s,box-shadow .18s}.auth-button:hover,.btn:hover{background:var(--primary-hover);box-shadow:0 9px 17px #d25f003b;transform:translateY(-1px)}.auth-button:disabled,.btn:disabled{cursor:wait;opacity:.72;transform:none}.auth-links{display:flex;justify-content:space-between;gap:14px;margin-top:23px;font-size:13px}.auth-links a{color:var(--primary-dark);font-weight:700;text-decoration:none}.field-error{margin-top:6px;color:#c52d36;font-size:12px;line-height:1.35}.alert{padding:12px 14px;margin-bottom:18px;border-radius:11px;font-size:13px;line-height:1.45}.alert-success{border:1px solid #bee5c9;background:#edfbf1;color:#176a38}.alert-danger{border:1px solid #f1c1c5;background:#fff1f2;color:#a8222a}@media(max-width:900px){.auth-shell{grid-template-columns:1fr}.auth-brand-panel{min-height:380px;padding:42px 8vw}.auth-brand-footer{margin-top:34px}.auth-login-panel{padding:30px 8vw 45px}}@media(max-width:520px){.auth-brand-panel{min-height:auto;padding:30px 24px}.auth-business-mark{margin-bottom:34px}.auth-brand-logo{width:52px;height:52px;border-radius:14px}.auth-brand-title{font-size:34px}.auth-brand-description{margin:15px 0 22px;font-size:14px}.auth-features{grid-template-columns:1fr 1fr}.auth-feature:last-child{grid-column:span 2;min-height:auto}.auth-login-panel{padding:20px 14px 32px}.auth-card{padding:27px 21px;border-radius:18px}.auth-links{align-items:center;flex-direction:column}}</style></head>
<body class="auth-page"><main class="auth-shell"><section class="auth-brand-panel" aria-label="Informasi {{ $branding['name'] }}"><div class="auth-brand-content"><div class="auth-business-mark"><div class="auth-brand-logo">@if($branding['logo'])<img src="{{ asset('storage/'.$branding['logo']) }}" alt="{{ $branding['name'] }} logo">@else<i class="fas fa-cash-register" aria-hidden="true"></i>@endif</div><span class="auth-brand-name" title="{{ $branding['name'] }}">{{ $branding['name'] }}</span></div><p class="auth-brand-kicker">Sistem point of sale</p><h1 class="auth-brand-title">Selamat Datang di <span>{{ $branding['name'] }}</span></h1><p class="auth-brand-description">{{ $branding['description'] ?: 'Kelola bisnis Anda dengan cepat, rapi, dan akurat.' }}</p><div class="auth-features" aria-label="Keunggulan sistem"><div class="auth-feature"><i class="fas fa-bolt" aria-hidden="true"></i><span>Proses lebih cepat</span></div><div class="auth-feature"><i class="fas fa-shield-alt" aria-hidden="true"></i><span>Data lebih aman</span></div><div class="auth-feature"><i class="fas fa-chart-line" aria-hidden="true"></i><span>Laporan real-time</span></div></div><p class="auth-brand-footer">{{ $branding['description'] ?: 'Solusi Digital untuk Bisnis Anda' }}</p></div></section><section class="auth-login-panel"><div class="auth-card"><div class="auth-card-heading"><div class="auth-card-logo">@if($branding['logo'])<img src="{{ asset('storage/'.$branding['logo']) }}" alt="{{ $branding['name'] }} logo">@else<i class="fas fa-cash-register" aria-hidden="true"></i>@endif</div>@yield('card_heading')</div>@yield('content')</div></section></main><script>document.querySelectorAll('[data-password-toggle]').forEach((b)=>{b.setAttribute('aria-label','Tampilkan password');b.setAttribute('aria-controls',b.dataset.passwordToggle);b.setAttribute('aria-pressed','false');b.querySelector('i').setAttribute('aria-hidden','true');b.addEventListener('click',()=>{const i=document.getElementById(b.dataset.passwordToggle),visible=i.type==='password';i.type=visible?'text':'password';b.setAttribute('aria-label',visible?'Sembunyikan password':'Tampilkan password');b.setAttribute('aria-pressed',String(visible));b.querySelector('i').classList.toggle('fa-eye',!visible);b.querySelector('i').classList.toggle('fa-eye-slash',visible)})});document.querySelectorAll('form[data-loading]').forEach((f)=>f.addEventListener('submit',()=>{const b=f.querySelector('button[type=submit]');if(b){b.disabled=true;b.innerHTML='<i class="fas fa-spinner fa-spin" aria-hidden="true"></i> Memproses...'}}));</script></body></html>
